using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

namespace BinaryEasy {
    public sealed class MessageViewer : Form {
        readonly MessageArchive archive;readonly DataGridView rows=new DataGridView();readonly ComboBox filter=new ComboBox();readonly CheckBox follow=new CheckBox();readonly Label count=new Label(),hint=new Label();readonly TextBox hex=new TextBox(),decoded=new TextBox(),original=new TextBox();readonly Timer timer=new Timer();readonly List<MessageEntry> shown=new List<MessageEntry>();bool selecting;
        public string RunDirectory {get;private set;}
        public MessageViewer(string directory,Scenario scenario){
            RunDirectory=directory;archive=new MessageArchive(directory,scenario);Text="송수신 상세 · "+scenario;Font=new Font("맑은 고딕",10);BackColor=Color.FromArgb(246,244,237);ForeColor=Color.FromArgb(35,57,47);ClientSize=new Size(1180,800);MinimumSize=new Size(1000,720);StartPosition=FormStartPosition.CenterParent;
            var page=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=4};page.RowStyles.Add(new RowStyle(SizeType.Absolute,54));page.RowStyles.Add(new RowStyle(SizeType.Absolute,42));page.RowStyles.Add(new RowStyle(SizeType.Percent,100));page.RowStyles.Add(new RowStyle(SizeType.Absolute,34));Controls.Add(page);
            page.Controls.Add(new Label{Text="송신·수신은 시험 시스템 기준입니다. 발송·수신 주체는 실제 시스템명으로 표시합니다.\r\n같은 내용의 반복 메시지도 매회 남깁니다. 원문은 선택한 행 아래에서 확인하세요.",Dock=DockStyle.Fill},0,0);
            var options=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};filter.DropDownStyle=ComboBoxStyle.DropDownList;filter.Width=180;filter.Items.AddRange(new object[]{"송수신 메시지 전체","송신 메시지","수신 메시지","조립·판정 자료","모든 자료"});filter.SelectedIndex=0;filter.AccessibleName="표시할 메시지";follow.Text="새 메시지 따라가기";follow.Checked=true;follow.AutoSize=true;follow.Padding=new Padding(10,4,0,0);count.AutoSize=true;count.Padding=new Padding(12,5,0,0);options.Controls.AddRange(new Control[]{filter,follow,count});page.Controls.Add(options,0,1);
            var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterWidth=7};page.Controls.Add(split,0,2);split.Panel1MinSize=150;split.Panel2MinSize=180;
            rows.Dock=DockStyle.Fill;rows.VirtualMode=true;rows.ReadOnly=true;rows.AllowUserToAddRows=false;rows.AllowUserToDeleteRows=false;rows.AllowUserToResizeRows=false;rows.RowHeadersVisible=false;rows.MultiSelect=false;rows.SelectionMode=DataGridViewSelectionMode.FullRowSelect;rows.BackgroundColor=Color.White;rows.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;rows.RowTemplate.Height=28;rows.ColumnHeadersHeight=34;rows.DefaultCellStyle.SelectionBackColor=Color.FromArgb(220,235,225);rows.DefaultCellStyle.SelectionForeColor=ForeColor;rows.AccessibleName="모든 회차의 송수신 메시지 목록";
            foreach(var pair in new[]{Tuple.Create("순서",45f),Tuple.Create("시각",100f),Tuple.Create("상세시험",230f),Tuple.Create("회차",45f),Tuple.Create("구분",60f),Tuple.Create("발송 → 수신",270f),Tuple.Create("메시지",140f),Tuple.Create("바이트",60f),Tuple.Create("조각",65f)})rows.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=pair.Item1,FillWeight=pair.Item2,SortMode=DataGridViewColumnSortMode.NotSortable});split.Panel1.Controls.Add(rows);
            rows.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.False;
            var minimums=new[]{50,100,135,50,55,300,100,60,45};for(int i=0;i<minimums.Length;i++)rows.Columns[i].MinimumWidth=minimums[i];
            rows.CellToolTipTextNeeded+=(s,e)=>{if(e.RowIndex<0||e.RowIndex>=shown.Count)return;var item=shown[e.RowIndex];e.ToolTipText=e.ColumnIndex==5?item.Sender+" → "+item.Receiver:item.TestTitle;};
            var tabs=new TabControl{Dock=DockStyle.Fill};foreach(var pair in new[]{Tuple.Create("원문 HEX",hex),Tuple.Create("해석 데이터",decoded),Tuple.Create("수집 원본",original)}){var tab=new TabPage(pair.Item1);var box=pair.Item2;box.Multiline=true;box.ReadOnly=true;box.Dock=DockStyle.Fill;box.ScrollBars=ScrollBars.Both;box.WordWrap=false;box.MaxLength=0;box.BackColor=Color.White;box.AccessibleName=pair.Item1;box.Font=new Font(pair.Item2==hex?"Consolas":"맑은 고딕",10);tab.Controls.Add(box);tabs.TabPages.Add(tab);}split.Panel2.Controls.Add(tabs);hint.Dock=DockStyle.Fill;hint.Padding=new Padding(0,6,0,0);page.Controls.Add(hint,0,3);
            rows.CellValueNeeded+=(s,e)=>{if(e.RowIndex>=shown.Count)return;var v=shown[e.RowIndex];object[] values={e.RowIndex+1,v.Time,v.TestTitle,v.Round,v.Direction,v.Sender+(String.IsNullOrEmpty(v.Receiver)?"":" → "+v.Receiver),v.Title,v.Frame&&v.Complete?(object)v.Bytes:"—",v.Parts.Count+"/"+v.ExpectedParts};e.Value=values[e.ColumnIndex];};
            rows.SelectionChanged+=(s,e)=>{if(!selecting&&rows.CurrentCell!=null){follow.Checked=false;ShowMessage();}};filter.SelectedIndexChanged+=(s,e)=>RefreshRows();follow.CheckedChanged+=(s,e)=>{if(follow.Checked)RefreshRows();};timer.Interval=350;timer.Tick+=(s,e)=>{if(archive.Refresh())RefreshRows();if(archive.LastError!=null)hint.Text=archive.LastError;};Shown+=(s,e)=>{split.SplitterDistance=Math.Max(180,split.Height/2);RefreshRows();timer.Start();};FormClosed+=(s,e)=>timer.Dispose();
        }
        void RefreshRows(){
            var current=rows.CurrentCell!=null&&rows.CurrentCell.RowIndex<shown.Count?shown[rows.CurrentCell.RowIndex]:null;shown.Clear();shown.AddRange(archive.Entries.Where(x=>filter.SelectedIndex==4||filter.SelectedIndex==0&&(x.Frame||x.Error!=null)||filter.SelectedIndex==1&&x.Direction=="송신"||filter.SelectedIndex==2&&x.Direction=="수신"||filter.SelectedIndex==3&&!x.Frame));
            selecting=true;try{rows.RowCount=shown.Count;rows.Invalidate();if(shown.Count>0){int at=follow.Checked?shown.Count-1:Math.Max(0,shown.IndexOf(current));rows.CurrentCell=rows.Rows[at].Cells[0];if(follow.Checked)rows.FirstDisplayedScrollingRowIndex=at;}}finally{selecting=false;}
            count.Text="송신 "+archive.Entries.Count(x=>x.Direction=="송신")+" · 수신 "+archive.Entries.Count(x=>x.Direction=="수신")+" · 검사 자료 "+archive.Entries.Count(x=>!x.Frame)+"건";ShowMessage();
        }
        void ShowMessage(){
            if(rows.CurrentCell==null||rows.CurrentCell.RowIndex>=shown.Count){hex.Text=archive.Entries.Count==0?"아직 수집된 메시지가 없습니다. 시험을 시작하면 목록이 갱신됩니다.":"현재 필터에 해당하는 자료가 없습니다. 다른 필터를 선택하세요.";decoded.Clear();original.Clear();hint.Text="수집된 기록은 삭제하지 않습니다.";return;}
            var row=shown[rows.CurrentCell.RowIndex];var view=archive.Load(row);var h=view.Hex??"";hex.Text=h.Length==0?(row.Frame&&!row.Complete?"표시 조각이 모두 도착하면 원문 HEX를 표시합니다. 현재 수집한 조각은 수집 원본 탭에서 확인하세요.":"이 자료에는 원문 HEX가 없습니다. 해석 데이터와 수집 원본 탭을 확인하세요."):String.Join(Environment.NewLine,Enumerable.Range(0,(h.Length+31)/32).Select(n=>String.Join(" ",Enumerable.Range(n*16,Math.Min(16,(h.Length+1)/2-n*16)).Select(i=>h.Substring(i*2,Math.Min(2,h.Length-i*2))))));decoded.Text=view.Json??"";original.Text=view.Original??"";hint.Text=String.IsNullOrEmpty(view.Notice)?row.TestTitle+" · "+row.Round+"회 · "+row.Title:view.Notice;
        }
        public void Render(string path,int width,int height){ClientSize=new Size(width,height);archive.ReadToEnd();Show();Application.DoEvents();follow.Checked=false;RefreshRows();if(shown.Count>0){selecting=true;rows.CurrentCell=rows.Rows[0].Cells[0];rows.FirstDisplayedScrollingRowIndex=0;selecting=false;ShowMessage();var check=archive.Load(shown[0]);if(!String.IsNullOrEmpty(check.Hex)&&hex.Text.Replace(" ","").Replace(Environment.NewLine,"")!=check.Hex)throw new InvalidOperationException("원문 HEX 표시가 잘렸습니다.");if(decoded.Text!=(check.Json??"")||original.Text!=(check.Original??""))throw new InvalidOperationException("해석 자료 또는 수집 원본 표시가 잘렸습니다.");}Application.DoEvents();using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(Point.Empty,Size));bmp.Save(path);}Close();}
    }
}
